import json,math,pathlib,collections,statistics,hashlib
src=pathlib.Path.cwd()/'data'/'draws.json';payload=json.loads(src.read_text(encoding='utf-8-sig'));d=payload['draws'];N=math.comb(45,6);w=[r['firstPrizeWinners'] for r in d];odd=collections.Counter(sum(n%2 for n in r['numbers']) for r in d)
examples=[]
for rnd,desc in [(1128,'홀수3·짝수3, 연속번호 없음. 이 자료에서1등당첨자수 최대인 사례.'),(1018,'6개 모두 홀수. 이 자료에서1등당첨자수 최소인 사례.'),(783,'14·15·16·17의4연속번호를 포함한 사례.')]:
 r=next(r for r in d if r['round']==rnd);examples.append({**r,'descriptionKo':desc,'oddCount':sum(n%2 for n in r['numbers']),'sum':sum(r['numbers']),'selectedAfterObservation':True})
q0=[math.comb(23,i)*math.comb(22,6-i)/N for i in range(7)]
facts={'sourceFile':str(src),'sourceSha256':hashlib.sha256(src.read_bytes()).hexdigest(),'drawCount':len(d),'firstRound':d[0]['round'],'lastRound':d[-1]['round'],'firstDate':d[0]['date'],'lastDate':d[-1]['date'],'officialFirstPrizeWinnerCountSummary':{'sum':sum(w),'minimum':min(w),'maximum':max(w),'mean':statistics.mean(w),'median':statistics.median(w),'zeroCountRounds':[r['round'] for r in d if r['firstPrizeWinners']==0],'minimumCountRounds':[r['round'] for r in d if r['firstPrizeWinners']==min(w)],'maximumCountRounds':[r['round'] for r in d if r['firstPrizeWinners']==max(w)],'interpretation':'회차별 공식 firstPrizeWinners 집계 합계. 서로 다른 사람의 수로 해석할 수 없으며 독립적인 추첨 표본은 회차 단위이다.'},'examples':examples,'observedOddCountHistogram':[odd[i] for i in range(7)],'fairOddCountCategorySizes':[math.comb(23,i)*math.comb(22,6-i) for i in range(7)],'fairOddCountCategoryProbabilities':q0,'combinationProbabilityDistinction':{'outcomeCount':N,'fairCategoryProbability':'N_c/N','fairParticularCombinationProbability':1/N,'fiveUniqueValidTicketsJackpotProbability':5/N,'fiveTicketPercent':500/N,'threeOddCategoryProbability':q0[3],'allOddCategoryProbability':q0[6],'point':'유형 자체의 출현확률이 높아도 그 안의 개별6개번호 조합이 더 높은확률을 갖는 것은 아니다.'},'purchaseMethodLimitations':{'availableDrawFields':list(d[0]),'missingFromThisDataset':['회차별 자동·수동·반자동 총 구매게임 수','선택방법별 비당첨 게임 자료','모든 판매조합의 구매 빈도','구매자 고유식별과 중복구매 여부'],'denominatorNeeded':'자동/수동별 1등당첨건수 / 각 방식의 전체 구매게임수. 회차·중복구매의 군집성도 고려해야 함.','winnerWeightedConfounding':'한 당첨조합을1등당첨자수만큼 복제하면 같은 추첨을 반복표본으로 취급하며 구매인기·판매량·중복구매를 추첨확률과 혼동한다.','prizeConfounding':'1등당첨금은 해당회차 배분금액과 공동당첨자수의 영향을 받으므로 당첨금액을 다음번호 예측력으로 해석하지 않는다.'},'dirichletClassificationModel':{'precondition':'서로 겹치지 않고 전체 조합공간을 모두 덮는 유한한 유형분할; N_c>0인 유형만 사용. 과거 회차를 각1표본으로 집계.','fairBaseline':'q0_c=N_c/N','prior':'theta ~ Dirichlet(alpha), alpha_c=tau*q0_c, tau>0','posterior':'theta | data ~ Dirichlet(alpha_c+n_c)','posteriorPredictiveCategory':'qhat_c=(alpha_c+n_c)/(tau+n)','marginalPosterior':'theta_c | data ~ Beta(alpha_c+n_c, tau+n-alpha_c-n_c)','credibleIntervalMeaning':'모형과 사전분포, 안정적 유형확률 가정하에서 미지의유형확률 theta_c에 대한 사후 불확실성. 미래예측 우월성을 실증적으로 증명하는 구간이 아님.','jointCombinationProbability':'P_model(S)=qhat_c/N_c for S in category c, additionally assuming uniformity within each category','individualCombinationCredibleInterval':'[BetaQuantile(.025),BetaQuantile(.975)]/N_c under same model','jackpotProbabilityForUniquePortfolio':'sum_c m_c*theta_c/N_c, where m_c distinct purchased tickets are in category c','portfolioUncertainty':'다른유형에 걸친 포트폴리오는 하나의Dirichlet표본에서 합계확률을 계산한다. 유형별구간 끝점을 더해95%구간이라 부르지 않는다.','exactJointLogGain':'log(qhat_c)-log(q0_c)=log(P_model(actualSix))+log(N)','baselineRecovery':'qhat_c=q0_c이면 모든6개조합에 대해1/N로 복원된다.','limitations':['유형빈도 차이는 관찰된차이이며 인과적영향을 입증하지 않는다.','홀짝·합계·연속번호 같은 중첩분류를 독립이라고 가정해 단순곱하지 않는다.','전체모형의6개번호 확률합이1인지 확인하고 실제나온6개조합의 전체로그점수로 순차평가한다.','유형경계·사전강도·모형 선택을 점수를본뒤 조정하면 같은과거자료의성능이 과대평가될수있다.','이미관찰한마지막104회는 새로운독립검증이 아니며 이번결과도 탐색적으로표시한다.','관찰자료가 기계적편향의가능성까지 모두 배제한다고 주장하지 않는다. 유의한미래예측력은 별도검증 대상이다.']},'primarySources':[{'title':'동행복권 공식 추첨결과','url':'https://m.dhlottery.co.kr/lt645/result','supports':'보관한공식자료의원출처; 통계는 기존 data/draws.json에서 직접계산'},{'title':'동행복권 공식 이용안내','url':'https://www.dhlottery.co.kr/lt645/intro','supports':'자동·수동·반자동방식, 같은번호의 수량지정/복사기능, 등위별당첨금을당첨자수로나눔'},{'title':'Aditya Guntuboyina, UC Berkeley STAT238 Lecture12 (2026)','url':'https://stat238.berkeley.edu/spring-2026/lecturetwelve238spring2026/','supports':'Dirichlet-Multinomial 사후갱신 및 사후평균 공식'},{'title':'Gneiting and Raftery (2007), Strictly Proper Scoring Rules','url':'https://sites.stat.washington.edu/people/raftery/Research/PDF/Gneiting2007jasa.pdf','supports':'실현된결과의 확률분포를 적절한로그점수로 평가하는원리'}]}
out=pathlib.Path(__file__).parent
(out/'lotto-winner-cases-classification-facts-20260913.json').write_text(json.dumps(facts,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
lines=['# 과거1등 사례와 유형분류 확률: 해석과 검증','',f'기존 공식자료는 **{len(d)}회(720~1241회, {d[0]["date"]}~{d[-1]["date"]})**이다. 회차별 `firstPrizeWinners`의 합은 **{sum(w):,}건**, 최솟값 **{min(w)}**, 최댓값 **{max(w)}**, 중앙값 **{statistics.median(w)}**이며1등당첨자0명인 회차는 없다. 이 합계를 서로 다른6,151명의 신원 수나6,151회의 독립 추첨으로 해석하면 안 된다. 추첨 결과를 학습하는 기본 단위는 **회차별6개번호 한 세트, 총522표본**이다. 공식자료원은 [동행복권 추첨결과](https://m.dhlottery.co.kr/lt645/result)이며, 여기의 집계는 보관된 `data/draws.json`에서 직접 계산했다.','', '| 회차·날짜 | 본번호 | 공식1등당첨자수 | 관찰한특징 |','|---|---|---:|---|']
for e in examples:lines.append(f'| {e["round"]}회 · {e["date"]} | '+', '.join(map(str,e['numbers']))+f' | {e["firstPrizeWinners"]} | {e["descriptionKo"]} |')
lines+=['','세 사례는 설명용으로 사후 선택했다. 흔한홀짝3:3도, 모두홀수도,4연속번호가있는조합도 실제로 당첨됐다. 극단적유형을 무조건제외하는필터는 일부당첨가능조합을제외한다. 반대로이예시가그유형을다음회차에추천할 근거도아니다.','','**당첨자수·구매방식·금액을 추첨확률과 분리해야 한다.** 한회차 당첨자수가많아도 추첨은한번이다. 결과를당첨자수만큼복제해학습하면 해당조합의구매인기·전체판매량·같은번호중복구매가섞인다. 공식안내는 동일번호의수량지정과복사를허용하고, 상위등위의배분금액을당첨자수로나눈다고설명한다. 그러므로고액당첨과낮은공동당첨자수역시곧바로예측력의증거가아니다. [공식이용안내](https://www.dhlottery.co.kr/lt645/intro)','','이자료에는자동·수동·반자동별전체구매게임수와비당첨게임이없다. 자동1등건수가많다는관찰만으로자동의게임당성공률이더높다고결론낼수없다. 필요한분모는각방법의전체구매게임수이며, 회차별차이와같은번호중복구매에따른군집성도고려해야한다. 이는단순한성공률의정의에서따른다.','','**유형확률과한조합확률은다르다.** N=8,145,060이고유형c에N_c개조합이있으면공정모형에서 P(유형c)=N_c/N이지만, 그안의특정6개조합은1/N이다. 예를들어홀짝3:3유형은2,727,340개조합을포함해33.484591%이고, 모두홀수유형은100,947개로1.239365%다. 각유형안의한조합확률은동일하다. 유형필터로고르더라도유효하고서로다른5게임의1등확률은 **5/N=0.000061386902%**다.','','유형을이용한모형은다음과같이일관되게만들수있다.','','1. 모든6개조합을서로겹치지않는유형으로나누고각유형의조합수N_c를정확히센다. 홀짝·합계·연속번호처럼서로겹치는조건들을그대로독립확률처럼곱하지않는다.','2. q0_c=N_c/N을공정기준으로놓고 α_c=τq0_c, τ>0인Dirichlet사전분포를둔다. 유형별회차수n_c로갱신하면사후분포는Dirichlet(α_c+n_c), 다음유형의모형확률은(α_c+n_c)/(τ+n)이다.','3. 유형내에서는조합을균등하게본다는추가가정하에서, 특정6개조합의모형확률은qhat_c/N_c다. 실제나온6개조합의전체로그점수차는log(qhat_c/q0_c)다. 이값을이전자료만이용한순차검증에서균등기준과비교한다.','4. θ_c의주변사후분포는Beta(α_c+n_c,τ+n−α_c−n_c)다. 그95%사후구간을N_c로나누면같은모형하의개별조합확률구간이다. **모형·사전분포에조건부인불확실성구간이며, 미래당첨우월성이검증됐다는뜻이아니다.** 서로다른유형의5게임확률은Σm_cθ_c/N_c이며, 공동Dirichlet표본으로구간을구한다. 개별유형구간의끝점을그대로더해95%구간이라고하지않는다.','','사후갱신공식은 [UC Berkeley 통계강의](https://stat238.berkeley.edu/spring-2026/lecturetwelve238spring2026/), 전체예측분포의로그점수원리는 [Gneiting·Raftery원논문](https://sites.stat.washington.edu/people/raftery/Research/PDF/Gneiting2007jasa.pdf)에근거한다. 유형크기로개별조합확률을나누는부분은이모형의추가가정과직접도출이다.','','이미확인한마지막104회는새로운독립검증자료가아니다. 이번유형분석도탐색적분석으로표시하고, 이후추첨전에저장한예측을별도로누적해야한다. 현재자료만으로미래예측력이입증됐다고하지않으며, 반대로가능한모든기계적편향이배제됐다고도주장하지않는다.']
(out/'LOTTO_WINNER_CASES_CLASSIFICATION.ko.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
